import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.Vrlv_RFs.js";const u=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"reference/faq.md","filePath":"reference/faq.md","lastUpdated":1794906572000}'),n={name:"reference/faq.md"};function d(i,e,s,h,l,c){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Questions people ask before and while using ktor-svelte. Each answer is short and links to the page with the details.</p><h2 id="the-idea" tabindex="-1">The idea <a class="header-anchor" href="#the-idea" aria-label="Permalink to &quot;The idea&quot;">​</a></h2><h3 id="why-adapter-static-and-no-server-side-rendering" tabindex="-1">Why <code>adapter-static</code> and no server-side rendering? <a class="header-anchor" href="#why-adapter-static-and-no-server-side-rendering" aria-label="Permalink to &quot;Why `adapter-static` and no server-side rendering?&quot;">​</a></h3><p>ktor-svelte exists to ship one JVM app. SSR needs a JavaScript runtime that renders every request, so production would need Node next to the JVM, or a JavaScript engine inside it. That means two processes or a slow embedded engine, two places for auth and config, and two things to deploy and monitor. With <code>adapter-static</code>, the frontend is plain files, Ktor is the only backend, and the JAR is the whole app.</p><h3 id="what-about-seo-and-the-first-paint" tabindex="-1">What about SEO and the first paint? <a class="header-anchor" href="#what-about-seo-and-the-first-paint" aria-label="Permalink to &quot;What about SEO and the first paint?&quot;">​</a></h3><p>Prerender every page whose content is known at build time with <code>export const prerender = true</code>. Those pages are real HTML that search engines and slow devices see right away. Pages that depend on data from your API render in the browser, which suits dashboards, admin areas and anything behind a login. A <a href="./../features/endpoints#sitemap-and-robots-txt">sitemap and robots.txt</a> are generated for you.</p><h3 id="can-i-still-add-ssr-later" tabindex="-1">Can I still add SSR later? <a class="header-anchor" href="#can-i-still-add-ssr-later" aria-label="Permalink to &quot;Can I still add SSR later?&quot;">​</a></h3><p>Yes, but not with ktor-svelte. Switch the frontend to <code>adapter-node</code>, run it as its own server, and keep Ktor as the API behind it. You lose the single JAR and the same-origin setup, and you need CORS or a proxy.</p><h3 id="do-i-need-node-in-production" tabindex="-1">Do I need Node in production? <a class="header-anchor" href="#do-i-need-node-in-production" aria-label="Permalink to &quot;Do I need Node in production?&quot;">​</a></h3><p>No. The frontend is inside the JAR, and production runs one JVM process. Node or Bun is only needed to build. See <a href="./../guide/deployment">Deployment</a>.</p><h2 id="writing-the-app" tabindex="-1">Writing the app <a class="header-anchor" href="#writing-the-app" aria-label="Permalink to &quot;Writing the app&quot;">​</a></h2><h3 id="how-do-i-load-data-for-a-page" tabindex="-1">How do I load data for a page? <a class="header-anchor" href="#how-do-i-load-data-for-a-page" aria-label="Permalink to &quot;How do I load data for a page?&quot;">​</a></h3><p>Call your Ktor routes from <code>load</code> in <code>+page.ts</code> or from the component, through the generated client. <code>+page.server.ts</code> and <code>+server.ts</code> need a Node server and do not exist here. Write that logic as a Ktor route instead. In a <code>load</code> function, use <code>apiWith(event)</code> or pass <code>{ fetch }</code>. See <a href="./../features/calling-the-api#in-load-functions">In load functions</a>.</p><h3 id="what-replaces-form-actions" tabindex="-1">What replaces form actions? <a class="header-anchor" href="#what-replaces-form-actions" aria-label="Permalink to &quot;What replaces form actions?&quot;">​</a></h3><p>A Ktor route that receives the form as JSON or form data. Validation errors come back as a 422 that <code>isValidationError</code> understands, so the form can show them next to each field. See <a href="./../features/validation">Validation</a>.</p><h3 id="does-a-dynamic-route-like-notes-id-work" tabindex="-1">Does a dynamic route like <code>/notes/[id]</code> work? <a class="header-anchor" href="#does-a-dynamic-route-like-notes-id-work" aria-label="Permalink to &quot;Does a dynamic route like `/notes/[id]` work?&quot;">​</a></h3><p>Yes. Unknown paths get the fallback page, and SvelteKit renders the route in the browser. List patterns in <code>paramRoutes</code> to serve the fallback for them even when a request does not accept HTML. See <a href="./ktor#serving-the-frontend">Ktor settings</a>.</p><h3 id="my-ktor-route-hides-a-page-why" tabindex="-1">My Ktor route hides a page. Why? <a class="header-anchor" href="#my-ktor-route-hides-a-page-why" aria-label="Permalink to &quot;My Ktor route hides a page. Why?&quot;">​</a></h3><p>A route of yours such as <code>get(&quot;/{slug}&quot;)</code> beats the frontend. Keep API routes under your API prefix, <code>/api</code> by default. The app logs which route hides which page.</p><h3 id="how-do-i-put-pages-behind-a-login" tabindex="-1">How do I put pages behind a login? <a class="header-anchor" href="#how-do-i-put-pages-behind-a-login" aria-label="Permalink to &quot;How do I put pages behind a login?&quot;">​</a></h3><p>Either declare <a href="./../features/auth#page-guards">page guards</a> for the pages that need a user, or take over routing with <code>routing = SvelteRouting.Manual</code> and wrap <code>svelte()</code> in <code>authenticate</code>. See <a href="./ktor#route-svelte">Route.svelte()</a> and <a href="./../features/auth">Auth</a>.</p><h3 id="how-do-i-keep-secrets-out-of-the-frontend" tabindex="-1">How do I keep secrets out of the frontend? <a class="header-anchor" href="#how-do-i-keep-secrets-out-of-the-frontend" aria-label="Permalink to &quot;How do I keep secrets out of the frontend?&quot;">​</a></h3><p>Read them from environment variables on the server, never in <code>publicConfig</code>. <code>svelteVerifyLeaks</code> fails the build when a secret value ends up in the built files. See <a href="./../features/runtime-config#secrets-in-the-frontend-build">Secrets in the frontend build</a>.</p><h2 id="developing" tabindex="-1">Developing <a class="header-anchor" href="#developing" aria-label="Permalink to &quot;Developing&quot;">​</a></h2><h3 id="which-port-do-i-open-while-developing" tabindex="-1">Which port do I open while developing? <a class="header-anchor" href="#which-port-do-i-open-while-developing" aria-label="Permalink to &quot;Which port do I open while developing?&quot;">​</a></h3><p>Ktor&#39;s, such as <code>http://localhost:8080</code>, not Vite&#39;s. The <a href="./../guide/dev-workflow#the-ready-banner">ready banner</a> prints it, and the browser opens it the first time.</p><h3 id="do-i-have-to-restart-after-a-kotlin-change" tabindex="-1">Do I have to restart after a Kotlin change? <a class="header-anchor" href="#do-i-have-to-restart-after-a-kotlin-change" aria-label="Permalink to &quot;Do I have to restart after a Kotlin change?&quot;">​</a></h3><p>No. <code>svelteDevAll</code> restarts the app, regenerates the TypeScript client, and open pages reload their data by themselves. See <a href="./../guide/dev-workflow#hot-reload-and-restart">Hot reload and restart</a>.</p><h3 id="how-do-i-debug-kotlin-and-the-frontend" tabindex="-1">How do I debug Kotlin and the frontend? <a class="header-anchor" href="#how-do-i-debug-kotlin-and-the-frontend" aria-label="Permalink to &quot;How do I debug Kotlin and the frontend?&quot;">​</a></h3><p>Start <code>Dev</code>, then <code>Debug app</code> for Kotlin and <code>Debug frontend</code> for the browser, or <code>Dev and debug</code> for both. Outside IntelliJ, attach a debugger to <code>127.0.0.1:5005</code>. See <a href="./../guide/dev-workflow#debugging">Debugging</a>.</p><h3 id="how-do-i-see-why-an-api-call-failed" tabindex="-1">How do I see why an API call failed? <a class="header-anchor" href="#how-do-i-see-why-an-api-call-failed" aria-label="Permalink to &quot;How do I see why an API call failed?&quot;">​</a></h3><p>Open the <a href="./../guide/dev-workflow#the-dev-panel">dev panel</a> with the <strong>API</strong> button. It lists every call with its status and validation errors, shows the server&#39;s exception as an overlay, and can replay a call or copy it as <code>curl</code>.</p><h3 id="how-do-i-try-the-app-from-my-phone-during-development" tabindex="-1">How do I try the app from my phone during development? <a class="header-anchor" href="#how-do-i-try-the-app-from-my-phone-during-development" aria-label="Permalink to &quot;How do I try the app from my phone during development?&quot;">​</a></h3><p>Set <code>dev { allowRemote = true }</code>, and only on a network you trust. The phone must also reach Vite&#39;s port. See <a href="./../guide/dev-workflow#the-dev-proxy">The dev proxy</a>.</p><h3 id="i-need-https-locally-for-secure-cookies-or-a-sign-in-provider" tabindex="-1">I need HTTPS locally, for <code>Secure</code> cookies or a sign-in provider. <a class="header-anchor" href="#i-need-https-locally-for-secure-cookies-or-a-sign-in-provider" aria-label="Permalink to &quot;I need HTTPS locally, for `Secure` cookies or a sign-in provider.&quot;">​</a></h3><p>Set <code>svelte { dev { https = true } }</code> and trust the development certificate once. See <a href="./../guide/dev-workflow#https-in-development">HTTPS in development</a>.</p><h2 id="checks-and-tests" tabindex="-1">Checks and tests <a class="header-anchor" href="#checks-and-tests" aria-label="Permalink to &quot;Checks and tests&quot;">​</a></h2><h3 id="which-checks-run-on-every-build" tabindex="-1">Which checks run on every build? <a class="header-anchor" href="#which-checks-run-on-every-build" aria-label="Permalink to &quot;Which checks run on every build?&quot;">​</a></h3><p><code>svelteVerifySync</code> before every frontend build, <code>svelteVerifyLeaks</code> before the build goes into the JAR, and <code>svelteVerifyTs</code> as part of <code>check</code>. The others are yours to add. See <a href="./../guide/checks-and-tooling">Checks and tooling</a>.</p><h3 id="can-i-write-browser-tests-in-kotlin" tabindex="-1">Can I write browser tests in Kotlin? <a class="header-anchor" href="#can-i-write-browser-tests-in-kotlin" aria-label="Permalink to &quot;Can I write browser tests in Kotlin?&quot;">​</a></h3><p>Yes. A test suite called <code>browserTest</code> gets Playwright, the packaged app and an <code>api</code> that speaks your own classes. <code>svelteRecordTest</code> writes the first test while you click. See <a href="./../guide/browser-tests">Browser tests</a>.</p><h3 id="how-do-i-check-accessibility" tabindex="-1">How do I check accessibility? <a class="header-anchor" href="#how-do-i-check-accessibility" aria-label="Permalink to &quot;How do I check accessibility?&quot;">​</a></h3><p>While you build a page, with the <strong>Accessibility</strong> section of the dev panel. For every prerendered page, with <code>./gradlew svelteVerifyA11y</code>. For pages behind a login, with <code>page.accessibilityProblems()</code> in a browser test. See <a href="./../guide/browser-tests#accessibility">Accessibility</a>.</p><h3 id="how-do-i-know-my-production-jar-works-before-i-deploy-it" tabindex="-1">How do I know my production JAR works before I deploy it? <a class="header-anchor" href="#how-do-i-know-my-production-jar-works-before-i-deploy-it" aria-label="Permalink to &quot;How do I know my production JAR works before I deploy it?&quot;">​</a></h3><p>Run <code>./gradlew svelteSmokeTest</code>. It starts the JAR in production mode and requests every prerendered page and the <code>GET</code> API routes. See <a href="./../guide/deployment#smoke-test">Smoke test</a>.</p><h2 id="running-in-production" tabindex="-1">Running in production <a class="header-anchor" href="#running-in-production" aria-label="Permalink to &quot;Running in production&quot;">​</a></h2><h3 id="how-do-i-deploy" tabindex="-1">How do I deploy? <a class="header-anchor" href="#how-do-i-deploy" aria-label="Permalink to &quot;How do I deploy?&quot;">​</a></h3><p>Build one JAR with <code>./gradlew buildFatJar</code> and run it with <code>java -jar</code>, in Docker, on Railway or as a systemd service. See <a href="./../guide/deployment">Deployment</a>.</p><h3 id="what-do-i-need-behind-nginx-or-caddy" tabindex="-1">What do I need behind nginx or Caddy? <a class="header-anchor" href="#what-do-i-need-behind-nginx-or-caddy" aria-label="Permalink to &quot;What do I need behind nginx or Caddy?&quot;">​</a></h3><p>Install <code>XForwardedHeaders</code>, send HSTS from the proxy, and do not compress twice. See <a href="./../guide/deployment#behind-a-reverse-proxy">Behind a reverse proxy</a>.</p><h3 id="how-do-i-find-out-about-errors-in-my-users-browsers" tabindex="-1">How do I find out about errors in my users&#39; browsers? <a class="header-anchor" href="#how-do-i-find-out-about-errors-in-my-users-browsers" aria-label="Permalink to &quot;How do I find out about errors in my users&#39; browsers?&quot;">​</a></h3><p>Turn on <code>frontendErrors()</code>, and uncaught errors from browsers land in your server log with the page and the request ID. See <a href="./../guide/monitoring#errors-from-the-browser">Monitoring</a>.</p><h3 id="how-do-i-know-which-version-is-running" tabindex="-1">How do I know which version is running? <a class="header-anchor" href="#how-do-i-know-which-version-is-running" aria-label="Permalink to &quot;How do I know which version is running?&quot;">​</a></h3><p>The startup log names the frontend fingerprint, and <code>application.buildInfo</code> has the version and commit. With <code>publicBuildInfo = true</code> the browser can read them too. See <a href="./../guide/monitoring#build-info">Build info</a>.</p><h3 id="is-there-a-health-check-for-my-load-balancer" tabindex="-1">Is there a health check for my load balancer? <a class="header-anchor" href="#is-there-a-health-check-for-my-load-balancer" aria-label="Permalink to &quot;Is there a health check for my load balancer?&quot;">​</a></h3><p>Yes: set <code>healthEndpoint = true</code> and point it at <code>GET /_ktor-svelte/health</code>. Add your own checks with <code>healthCheck { }</code>. See <a href="./../features/endpoints#health-endpoint">Health endpoint</a>.</p><h3 id="something-is-wrong-with-my-setup-where-do-i-start" tabindex="-1">Something is wrong with my setup. Where do I start? <a class="header-anchor" href="#something-is-wrong-with-my-setup-where-do-i-start" aria-label="Permalink to &quot;Something is wrong with my setup. Where do I start?&quot;">​</a></h3><p>Run <code>./gradlew svelteDoctor</code> for the frontend setup and <code>./gradlew svelteConfig</code> for the settings in effect. Then see <a href="./troubleshooting">Troubleshooting</a>.</p>',59)])])}const f=o(n,[["render",d]]);export{u as __pageData,f as default};
